sql_query:
SELECT holding_id, investor_id, investment_name, category
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        WHERE category IS NULL OR TRIM(category) = '';

SELECT holding_id, investor_id, investment_name, sector
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        WHERE sector IS NULL OR TRIM(sector) = '';

SELECT holding_id, investor_id, investment_name, returns_pct
            FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
            WHERE returns_pct < -20;

SELECT holding_id, investor_id, investment_name, segment
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        WHERE segment IS NULL OR TRIM(segment) = '';

SELECT holding_id, investor_id, investment_name, investment_type
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        WHERE investment_type IS NULL OR TRIM(investment_type) = '';

SELECT portfolio_health_id, investor_id, risk_score
            FROM ATOM_ENTITY_PORTFOLIO_HEALTH_001
            WHERE risk_score > 80;
